template <typename T>
T get_abs_value(T x) { return (x < 0) ? (-x) : x; }

long_type mod_exp(long_type base, long_type exp, long_type mod) {
	if(exp <= 0) return 1;
	long_type half = mod_exp(base, exp/2, mod);
	half = half * half % mod;
	return (exp & 1) ? half * base % mod : half;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	cout << fixed << setprecision(10);
	int N, M;
	long_type mod;
	cin >> N >> M >> mod;
	vector<long_type> factorials(N+1, 1), inv_factorials(N+1, 1);
	for(int i = 1; i <= N; i++) {
		factorials[i] = factorials[i-1] * i % mod;
		inv_factorials[i] = inv_factorials[i-1] * mod_exp(i, mod-2, mod) % mod;
	}
	vector<long_type> count_vec(M+1, 0);
	vector<long_type> sum_vec(M+1, 0);
	count_vec[0] = 1;
	for(int m = 1; m <= M; m++) {
		for(int k = 0; k < m; k++) {
			long_type left_c = count_vec[k] * inv_factorials[k] % mod;
			long_type right_c = count_vec[m-1-k] * inv_factorials[m-1-k] % mod;
			long_type left_s = sum_vec[k] * inv_factorials[k] % mod;
			long_type right_s = sum_vec[m-1-k] * inv_factorials[m-1-k] % mod;
			count_vec[m] += left_c * right_c % mod * (m+1);
			sum_vec[m] += (left_s * right_s + left_c * right_s + left_s * right_c) % mod * (m+1);
			sum_vec[m] += left_c * right_c % mod * (k*(k+1)+(m-k)*(m-k-1))/2 % mod;
		}
		count_vec[m] = count_vec[m] % mod * factorials[m-1] % mod;
		sum_vec[m] = sum_vec[m] % mod * factorials[m-1] % mod;
	}
	vector<vector<long_type>> count_res(N+1, vector<long_type>(M+1, 0));
	vector<vector<long_type>> sum_res(N+1, vector<long_type>(M+1, 0));
	count_res[0][0] = 1;
	for(int i = 1; i <= N; i++) {
		for(int j = 0; j <= min(i, M); j++) {
			count_res[i][j] = count_res[i-1][j];
			sum_res[i][j] = sum_res[i-1][j];
			if(j == i) {
				count_res[i][j] += count_vec[i] * inv_factorials[i] % mod;
				sum_res[i][j] += sum_vec[i] * inv_factorials[i] % mod;
			}
			for(int k = 1; k <= min(j, i-1); k++) {
				long_type c = count_vec[k] * inv_factorials[k] % mod;
				long_type s = sum_vec[k] * inv_factorials[k] % mod;
				count_res[i][j] += count_res[i-1-k][j-k] * c % mod;
				sum_res[i][j] += (sum_res[i-1-k][j-k] * c + count_res[i-1-k][j-k] * s) % mod;
			}
			count_res[i][j] %= mod;
			sum_res[i][j] %= mod;
		}
	}
	long_type final_ans = sum_res[N][M] * factorials[M] % mod;
	cout << final_ans << "\n";
}
